$cache=@{}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function RawEntry([string]$p){$f=Get-Item -LiteralPath ([IO.Path]::GetFullPath($p)) -Force;Need (!$f.PSIsContainer) 'Expected file';return [ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $f.FullName -Algorithm SHA256).Hash.ToLowerInvariant()}}
function E([string]$p){$key=([IO.Path]::GetFullPath($p)).ToLowerInvariant();if(!$cache.ContainsKey($key)){$cache[$key]=RawEntry $p};return $cache[$key]}
function Bind($rows){foreach($row in @($rows)){Need ($row.path -and $null -ne $row.bytes -and $row.sha256 -match '^[0-9a-fA-F]{64}$') 'Malformed Entry';$a=E $row.path;Need ($a.bytes -eq $row.bytes -and $a.sha256 -ieq $row.sha256) ('Changed or conflicting Entry: '+$row.path)}}
function Pin([string]$relative,[long]$bytes,[string]$sha){$e=[ordered]@{path=(Join-Path $tests $relative);bytes=$bytes;sha256=$sha};Bind @($e);return E $e.path}
function J([string]$p){return ([IO.File]::ReadAllText($p)|ConvertFrom-Json)}
function Fresh($paths){foreach($p in @($paths)){Need (!(Test-Path -LiteralPath $p)) ('Retained artifact protected: '+$p)}}
function WriteNew([string]$p,[byte[]]$bytes){$stream=[IO.File]::Open($p,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$stream.Write($bytes,0,$bytes.Length)}finally{$stream.Dispose()}}
function Dom([string]$text){$x=New-Object Xml.XmlDocument;$x.PreserveWhitespace=$true;$x.LoadXml($text);return ,$x}
function One($x,[string]$path){$rows=$x.SelectNodes($path);Need ($rows.Count -eq 1) ('Expected one XML node: '+$path);return ,$rows[0]}
function Num($value){$n=if($value -is [ValueType]){[double]$value}else{[double]::Parse([string]$value,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture)};Need (![double]::IsNaN($n) -and ![double]::IsInfinity($n)) 'Nonfinite number';return $n}
function Same($a,$b){return ($a.path -ieq $b.path -and $a.bytes -eq $b.bytes -and $a.sha256 -ieq $b.sha256)}
function FinalRehash(){foreach($e in @($cache.Values)){$a=RawEntry $e.path;Need (Same $a $e) ('Changed during input preparation: '+$e.path)}}
function Owned($entry,[bool]$python){Bind @($entry);$c=J $entry.path;$typed=if($python){$c.typed_returncode_captured_immediately}else{$c.typed_LASTEXITCODE_captured_immediately};Need ($c.direct_native_call -and $c.owned_call_exited -and $typed -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure) 'Actual owned immediate typed exit0 required';Bind @($c.program);if($c.log){Bind @($c.log)};return $c}
# Literal JDsOutputTime::GetNextTime control flow; do not round, snap or interpolate times.
function NextTime([double]$t,$state,$segments){
  if($state.last_input -ge 0 -and $t -eq $state.last_input){return $state.last_output};$state.last_input=$t
  $tb=[double]$segments[$state.base].time;$nextAnchor=[double]::MaxValue;if($state.base+1 -lt $segments.Count){$nextAnchor=[double]$segments[$state.base+1].time}
  while($t -ge $nextAnchor){$state.base++;$tb=[double]$segments[$state.base].time;$nextAnchor=[double]::MaxValue;if($state.base+1 -lt $segments.Count){$nextAnchor=[double]$segments[$state.base+1].time}}
  if($t -lt $tb){$next=$tb}else{$cadence=[double]$segments[$state.base].timeout;$nt=[long][Math]::Floor(($t-$tb)/$cadence);$next=$tb+$cadence*$nt;while($next -le $t){$next=$tb+$cadence*$nt;$nt++};if($next -gt $nextAnchor){$next=$nextAnchor}}
  $state.last_output=[double]$next;return [double]$next
}
function Schedule($oldJob){
  $dt=[Math]::Pow(2,-19);$steps=1048576;$end=2.0
  $segments=@(@{time=0.0;timeout=64*$dt},@{time=5120*$dt;timeout=$dt},@{time=5376*$dt;timeout=64*$dt},@{time=65536*$dt;timeout=1024*$dt},@{time=0.5;timeout=0.03125})
  $full=New-Object 'Collections.Generic.SortedSet[int]'
  for($k=0;$k -le 65536;$k+=64){[void]$full.Add($k)};for($k=5120;$k -le 5376;$k++){[void]$full.Add($k)};for($k=66560;$k -le 262144;$k+=1024){[void]$full.Add($k)};for($k=278528;$k -le 4784128;$k+=16384){[void]$full.Add($k)};[void]$full.Add(4798782)
  $original=@($full);Need ($original.Count -eq 1746 -and $original[-1] -eq 4798782 -and @($oldJob.saved_clock_table).Count -eq 1746) 'Original1746 mid clock plan required'
  for($i=0;$i -lt 1746;$i++){Need ($oldJob.saved_clock_table[$i].part -eq $i -and $oldJob.saved_clock_table[$i].completed_steps -eq $original[$i] -and $oldJob.saved_clock_table[$i].saved_step -eq $(if($i){$original[$i]-1}else{0})) 'Retained mid integer clock table differs'}
  $wanted=@($original|Where-Object{$_ -le $steps});Need ($wanted.Count -eq 1517 -and $wanted[-1] -eq $steps) 'Bounded first1517 plan differs'
  $state=@{base=0;last_input=-1.0;last_output=0.0};$rows=New-Object 'Collections.Generic.List[object]';[void]$rows.Add([ordered]@{part=0;completed_steps=0;saved_step=0;time_s=0.0});$t=0.0;$next=NextTime 0.0 $state $segments
  for($completed=1;$completed -le $steps;$completed++){$t+=$dt;if($t -ge $next -or $completed -eq $steps){[void]$rows.Add([ordered]@{part=$rows.Count;completed_steps=$completed;saved_step=$completed-1;time_s=[double]$t});$next=NextTime $t $state $segments}}
  Need ($rows.Count -eq 1517 -and $t -eq $end -and $steps*$dt -eq $end) 'Literal replay/end differs'
  $jsonDifferences=0;$jsonMaximum=0.0
  for($i=0;$i -lt 1517;$i++){
    Need ($rows[$i].part -eq $i -and $rows[$i].completed_steps -eq $wanted[$i] -and $rows[$i].saved_step -eq $(if($i){$wanted[$i]-1}else{0}) -and [BitConverter]::DoubleToInt64Bits($rows[$i].time_s) -eq [BitConverter]::DoubleToInt64Bits([double]$wanted[$i]*$dt)) 'Scheduler replay/integer union differs'
    $difference=[Math]::Abs((Num $oldJob.saved_clock_table[$i].time_s)-$rows[$i].time_s);if($difference -ne 0){$jsonDifferences++};$jsonMaximum=[Math]::Max($jsonMaximum,$difference)
  }
  Need ($rows[203].completed_steps -eq 5243 -and $rows[1468].time_s -eq 0.5 -and $rows[1469].time_s -eq 0.53125 -and $rows[1516].time_s -eq 2 -and @($rows|Where-Object{$_.completed_steps -gt 5243}).Count -eq 1313) 'Original event/late cadence/drain coverage differs'
  return @{table=$rows.ToArray();segments=$segments;dt=$dt;steps=$steps;end=$end;JSON_time_differences=$jsonDifferences;JSON_time_max_difference=$jsonMaximum}
}

